package com.coffeeshop.controller;import com.coffeeshop.model.RefundModels.*;import com.coffeeshop.security.ApplicationSession;import com.coffeeshop.service.RefundService;import javafx.application.Platform;import javafx.beans.property.SimpleStringProperty;import javafx.fxml.FXML;import javafx.geometry.Insets;import javafx.scene.control.*;import javafx.scene.layout.GridPane;import java.math.BigDecimal;import java.util.*;import java.util.concurrent.CompletableFuture;public final class RefundController{private final RefundService service;private final ApplicationSession session;@FXML private ComboBox<Payment>paymentBox;@FXML private TableView<Refund>refundTable;@FXML private TableColumn<Refund,String>orderColumn,methodColumn,amountColumn,reasonColumn,userColumn,timeColumn;@FXML private Label messageLabel;public RefundController(RefundService s,ApplicationSession a){service=Objects.requireNonNull(s);session=Objects.requireNonNull(a);}@FXML private void initialize(){orderColumn.setCellValueFactory(v->text(v.getValue().orderNumber()));methodColumn.setCellValueFactory(v->text(v.getValue().method()));amountColumn.setCellValueFactory(v->text(v.getValue().amount().toPlainString()));reasonColumn.setCellValueFactory(v->text(v.getValue().reason()));userColumn.setCellValueFactory(v->text(v.getValue().user()));timeColumn.setCellValueFactory(v->text(v.getValue().refundedAt().toString().replace('T',' ')));refresh();}@FXML private void refresh(){CompletableFuture.supplyAsync(service::catalog).whenComplete((v,e)->Platform.runLater(()->{if(e!=null){messageLabel.setText("Unable to load refunds.");return;}paymentBox.getItems().setAll(v.payments());refundTable.getItems().setAll(v.refunds());messageLabel.setText(v.refunds().isEmpty()?"No refunds have been recorded.":"");}));}@FXML private void create(){Payment p=paymentBox.getValue();if(p==null){messageLabel.setText("Select an original payment.");return;}Dialog<Input>d=new Dialog<>();d.setTitle("Refund "+p.orderNumber());ButtonType save=new ButtonType("Record refund",ButtonBar.ButtonData.OK_DONE);d.getDialogPane().getButtonTypes().addAll(ButtonType.CANCEL,save);TextField amount=new TextField(p.remaining().toPlainString()),reason=new TextField(),reference=new TextField();TextArea notes=new TextArea();notes.setPrefRowCount(3);GridPane g=new GridPane();g.setHgap(12);g.setVgap(8);g.setPadding(new Insets(8));field(g,0,"Remaining refundable",new Label(p.remaining().toPlainString()));field(g,1,"Refund amount",amount);field(g,2,"Reason",reason);field(g,3,"Reference",reference);field(g,4,"Notes",notes);d.getDialogPane().setContent(g);d.setResultConverter(b->{if(b!=save)return null;BigDecimal n;try{n=new BigDecimal(amount.getText());}catch(Exception e){n=null;}return new Input(n,reason.getText(),reference.getText(),notes.getText());});d.showAndWait().ifPresent(i->CompletableFuture.runAsync(()->service.refund(p,i.amount,i.reason,i.reference,i.notes,user())).whenComplete((v,e)->Platform.runLater(()->{if(e==null){refresh();messageLabel.setText("Refund recorded.");}else messageLabel.setText(message(e));})));}private record Input(BigDecimal amount,String reason,String reference,String notes){}private long user(){return session.currentUser().orElseThrow().userId();}private static void field(GridPane g,int r,String n,Control c){g.add(new Label(n),0,r);c.setMaxWidth(Double.MAX_VALUE);g.add(c,1,r);}private static SimpleStringProperty text(String s){return new SimpleStringProperty(s);}private static String message(Throwable e){Throwable x=e;while(x.getCause()!=null)x=x.getCause();return x instanceof IllegalArgumentException||x instanceof IllegalStateException?x.getMessage():"Unable to record refund.";}}
